// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(newOwner != address(0));
        vm.prank(nonOwner);
        try c.setOwner(newOwner) {
            assertTrue(c.owner() == address(0) || msg.sender == c.owner());
        } catch {
            assertTrue(true);
        }
    }
}
